         box-shadow: 0 14px 32px rgba(56, 189, 248, 0.24);
       }

       button:focus {
         outline: 3px solid #f8fafc;
         outline-offset: 3px;
       }

       .status-message {
         min-height: 1.5em;
         color: #bbf7d0;
         font-weight: 700;
       }

       @media (prefers-reduced-motion: reduce) {
         *,
         *::before,
         *::after {
           scroll-behavior: auto !important;
           transition-duration: 0.01ms !important;
           animation-duration: 0.01ms !important;
           animation-iteration-count: 1 !important;
         }
       }

       @media (forced-colors: active) {
         .support-card,
         input,
         button {
           border: 1px solid CanvasText;
         }

         button {
           color: ButtonText;
           background: ButtonFace;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#main">Skip to main content</a>
     <main id="main">
       <div id="app"></div>
     </main>

     <script>
       const fields = [
         {
           id: "full-name",
           name: "fullName",
           label: "Full name",
           type: "text",
           autocomplete: "name",
           required: true,
           error: "Error: Enter your full name."
         },
         {
           id: "email",
           name: "email",
           label: "Email address",
           type: "email",
           autocomplete: "email",
           required: true,
           error: "Error: Enter a valid email address, such as name@example.com."
         },
         {
           id: "phone",
           name: "phone",
           label: "Phone number",
           type: "tel",
           autocomplete: "tel",
           required: false,
           helperText: "Use international format, for example +1 555 123 4567."
         }
       ];

       function RequiredMark() {
         return '<span class="required-marker" aria-hidden="true">*</span>';
       }

       function FormField(field) {
         const describedBy = field.helperText ? ` aria-describedby="${field.id}-help"` : "";
         const required = field.required ? " required" : "";
         const marker = field.required ? ` ${RequiredMark()}` : "";
         const helper = field.helperText
           ? `<p class="helper-text" id="${field.id}-help">${field.helperText}</p>`
           : "";

         return `
           <div class="form-field">
             <label for="${field.id}">${field.label}${marker}</label>
             <input id="${field.id}" name="${field.name}" type="${field.type}" autocomplete="${field.autocomplete}"${required}${describedBy}>
             ${helper}
           </div>
         `;
       }

       function ContactForm() {
         return `
           <section class="support-card" aria-labelledby="support-title">
             <p class="eyebrow">Support</p>
             <h1 id="support-title">Contact our team</h1>
             <p class="intro">Tell us how to reach you and a support specialist will follow up shortly.</p>
             <form id="support-form" novalidate>
               <p class="required-note"><span aria-hidden="true">*</span> indicates a required field.</p>
               ${fields.map(FormField).join("")}
               <div class="actions">
                 <button type="submit">Send request</button>
               </div>
               <p class="status-message" id="form-status" aria-live="polite"></p>
             </form>
           </section>
         `;
       }

       function App() {
         return ContactForm();
       }

       function removeError(input) {
         const error = document.getElementById(`${input.id}-error`);
         if (error) {
           error.remove();
         }

         const helper = document.getElementById(`${input.id}-help`);
         input.removeAttribute("aria-invalid");
         input.setAttribute("aria-describedby", helper ? helper.id : "");

         if (!helper) {
           input.removeAttribute("aria-describedby");
         }
       }

       function showError(input, message) {
         removeError(input);

         const error = document.createElement("p");
         error.className = "error-message";
         error.id = `${input.id}-error`;
         error.textContent = message;
         input.insertAdjacentElement("afterend", error);
         input.setAttribute("aria-invalid", "true");

         const helper = document.getElementById(`${input.id}-help`);
         input.setAttribute(
           "aria-describedby",
           helper ? `${helper.id} ${error.id}` : error.id
         );
       }

       function validateField(field) {
         const input = document.getElementById(field.id);
         removeError(input);

         if (!input.checkValidity()) {
           showError(input, field.error);
           return false;
         }

         return true;
       }

       document.getElementById("app").innerHTML = App();

       const form = document.getElementById("support-form");
       const status = document.getElementById("form-status");

       fields.forEach((field) => {
         document.getElementById(field.id).addEventListener("input", () => {
           validateField(field);
           status.textContent = "";
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         const invalidField = fields.find((field) => !validateField(field));

         if (invalidField) {
           document.getElementById(invalidField.id).focus();
           status.textContent = "";
           return;
         }

         status.textContent = "Thanks. Your support request is ready to send.";
         form.reset();
       });
     </script>
   </body>
 </html>

